* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  background: #2b2d42;
  color: #edf2f4;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 1rem;
}

.card {
  background: #1a1b2e;
  border: 4px solid #ef233c;
  border-radius: 0;
  box-shadow: 8px 8px 0 #0b0c1a;
  padding: 1.5rem;
  width: 100%;
  max-width: 480px;
}

h1 {
  font-size: 1.6rem;
  margin-bottom: 1rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: #ef233c;
  text-shadow: 2px 2px 0 #0b0c1a;
}

.input-row {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

input[type="text"] {
  flex: 1;
  padding: 0.6rem;
  font-size: 1rem;
  border: 3px solid #8d99ae;
  background: #edf2f4;
  color: #1a1b2e;
  border-radius: 0;
}

input[type="text"]:focus {
  outline: 3px solid #ef233c;
  outline-offset: 2px;
}

button {
  font-size: 1rem;
  padding: 0.6rem 1.2rem;
  border: 3px solid #ef233c;
  background: #ef233c;
  color: #edf2f4;
  font-weight: bold;
  text-transform: uppercase;
  cursor: pointer;
  border-radius: 0;
  transition: background 0.1s, transform 0.1s;
}

button:hover {
  background: #d90429;
}

button:active {
  transform: translate(2px, 2px);
  box-shadow: none;
}

button:focus-visible {
  outline: 3px solid #edf2f4;
  outline-offset: 2px;
}

.counts {
  display: flex;
  justify-content: space-between;
  margin-bottom: 1rem;
  font-size: 1rem;
  color: #8d99ae;
}

.counts span span {
  color: #edf2f4;
  font-weight: bold;
}

ul {
  list-style: none;
}

li {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.6rem;
  border-bottom: 2px solid #2b2d42;
}

li:last-child {
  border-bottom: none;
}

li input[type="checkbox"] {
  width: 1.4rem;
  height: 1.4rem;
  accent-color: #ef233c;
  cursor: pointer;
}

li span {
  flex: 1;
  word-break: break-word;
}

li button {
  padding: 0.3rem 0.8rem;
  font-size: 0.9rem;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0,0,0,0);
  border: 0;
}

@media (max-width: 400px) {
  .card { padding: 1rem; }
  h1 { font-size: 1.3rem; }
  .input-row { flex-direction: column; }
  button { width: 100%; }
}

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const list = document.getElementById('todo-list');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');

let nextId = 1;
let tasks = [];

function updateCounts() {
  totalEl.textContent = tasks.length;
  remainingEl.textContent = tasks.filter(t => !t.done).length;
}

function createTaskElement(task) {
  const li = document.createElement('li');

  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.id = 'todo-check-' + task.id;
  checkbox.checked = task.done;
  checkbox.setAttribute('aria-label', 'Mark task ' + task.id + ' as done');

  const span = document.createElement('span');
  span.id = 'todo-text-' + task.id;
  span.textContent = task.text;

  const delBtn = document.createElement('button');
  delBtn.type = 'button';
  delBtn.id = 'todo-delete-' + task.id;
  delBtn.textContent = 'Delete';
  delBtn.setAttribute('aria-label', 'Delete task ' + task.id);

  checkbox.addEventListener('change', () => {
    task.done = checkbox.checked;
    updateCounts();
  });

  delBtn.addEventListener('click', () => {
    tasks = tasks.filter(t => t.id !== task.id);
    li.remove();
    updateCounts();
  });

  li.appendChild(checkbox);
  li.appendChild(span);
  li.appendChild(delBtn);
  return li;
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;
  const task = { id: nextId++, text, done: false };
  tasks.push(task);
  list.appendChild(createTaskElement(task));
  input.value = '';
  input.focus();
  updateCounts();
}

addBtn.addEventListener('click', addTask);
input.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') addTask();
});

updateCounts();
